css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .72); position: relative; overflow: hidden; }
.loader::after { content: ''; position: absolute; left: 2%; bottom: 14%; width: 104%; height: 5%; border-radius: 999px; background: #cbd5e1; transform-origin: left center; transform: rotate(-37.6deg); }
.loader span { position: absolute; left: 0; bottom: 4%; width: 22%; height: 12%; border-radius: 3px; background: linear-gradient(var(--accent), var(--accent-2)); animation: escalate calc(var(--loader-speed) * 2.4) linear infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * -.48); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * -.96); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * -1.44); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * -1.92); }
@keyframes escalate { 0% { opacity: 0; transform: translate(0, 0); } 14% { opacity: 1; } 86% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(var(--loader-size) * .76), calc(var(--loader-size) * -.58)); } }
